import 'package:shared_preferences/shared_preferences.dart';
class Session { static String? token; static String role='customer'; static bool isLoggedIn=false; static Future<void> save(String t,{String userRole='customer'}) async {token=t;role=userRole;isLoggedIn=true;final p=await SharedPreferences.getInstance();await p.setString('token',t);await p.setString('role',userRole);} static Future<void> load() async {final p=await SharedPreferences.getInstance();token=p.getString('token');role=p.getString('role')??'customer';isLoggedIn=token!=null;} static Future<void> clear() async {final p=await SharedPreferences.getInstance();await p.remove('token');await p.remove('role');token=null;role='customer';isLoggedIn=false;} }
